// 1. Make sure Set Personal Settings has been filled in
const s = $('Set Personal Settings').first().json;
const text = (v) => String(v == null ? '' : v).trim();
const missing = [];
const emails = text(s.yourEmail).split(',').map((e) => e.trim()).filter(Boolean);
if (!emails.length || emails.some((e) => !e.includes('@') || /example\.com$/i.test(e))) missing.push('your email');
if (!text(s.yourName) || /^your name$/i.test(text(s.yourName))) missing.push('your name');
if (!text(s.businessName) || /^your business$/i.test(text(s.businessName))) missing.push('your business name');
if (!text(s.whatYouSell) || /^replace/i.test(text(s.whatYouSell))) missing.push('what you sell');
if (!/docs\.google\.com\/spreadsheets\/d\//i.test(text(s.callLogSheetUrl))) missing.push('the full link to your Google Sheet');
const booking = text(s.bookingLink);
if (booking && !/^https?:\/\//i.test(booking)) missing.push('a booking link that starts with https:// (or leave it empty)');
if (missing.length) {
  throw new Error('Open the Set Personal Settings node and fill in: ' + missing.join(', '));
}

// 2. Read the Fireflies event (works with Webhooks V2 and the older V1 format)
const body = $('When Call Transcribed').first().json.body || {};
const meetingId = text(body.meeting_id || body.meetingId);
const event = text(body.event || body.eventType);
const isTranscribed = /^meeting\.transcribed$/i.test(event) || /^transcription complete/i.test(event);
let reason = '';
if (!meetingId) reason = 'No meeting ID in the request';
else if (!isTranscribed) reason = 'Ignored event: ' + (event || 'none');
else if (body.reprocessed_at) reason = 'Ignored a resend of a meeting that was already processed';

return [{ json: { meetingId, event, process: !reason, reason } }];

// 1. Check what Fireflies sent back
const res = $input.first().json;
const status = Number(res.statusCode || 200);
let body = res.body;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch (e) { body = {}; }
}
body = body || {};
const errors = Array.isArray(body.errors) ? body.errors : [];
const errorText = errors.map((e) => String(e.message || '')).join('; ');

if (status === 401 || status === 403 || errors.some((e) => /auth|api key|unauthori[sz]ed|forbidden/i.test(String((e.extensions && e.extensions.code) || '') + ' ' + String(e.message || '')))) {
  throw new Error('Fireflies did not accept the API key. Open Fetch Transcript From Fireflies and check its Bearer YOUR_TOKEN_HERE credential.');
}
if (status === 429 || errors.some((e) => /rate.?limit|too many/i.test(String((e.extensions && e.extensions.code) || '') + ' ' + String(e.message || '')))) {
  throw new Error('Fireflies says too many API requests. The free plan allows 500 a day. Try again later.');
}
const notFound = errors.some((e) => /not.?found/i.test(String((e.extensions && e.extensions.code) || '') + ' ' + String(e.message || '')));
const t = body.data && body.data.transcript;
// A meeting Fireflies cannot find (for example the Send Test Event ping): stop quietly
if (notFound || (!t && !errors.length && status < 300)) return [];
if (status >= 300 || errors.length || !t) {
  throw new Error('Fireflies returned an error: ' + (errorText || ('HTTP ' + status)));
}

// 2. Find the other person on the call
const s = $('Set Personal Settings').first().json;
const mine = String(s.yourEmail || '').split(',').map((e) => e.trim().toLowerCase()).filter(Boolean);
const attendees = Array.isArray(t.meeting_attendees) ? t.meeting_attendees.filter(Boolean) : [];
const emails = [
  ...attendees.map((a) => a.email),
  ...(Array.isArray(t.participants) ? t.participants : []).flatMap((p) => String(p || '').split(','))
]
  .map((e) => String(e || '').trim().toLowerCase())
  .filter((e) => e.includes('@') && !mine.includes(e) && !e.endsWith('@fireflies.ai'));
const contactEmail = emails[0] || '';
const match = attendees.find((a) => String(a.email || '').trim().toLowerCase() === contactEmail) || {};
const fromAddress = contactEmail.split('@')[0].split(/[._\-+0-9]/)[0] || '';
const contactName = String(match.displayName || '').trim() ||
  (fromAddress ? fromAddress.charAt(0).toUpperCase() + fromAddress.slice(1) : '');

// 3. Turn the sentences into plain text for the AI
const sentences = Array.isArray(t.sentences) ? t.sentences : [];
let transcriptText = sentences
  .map((x) => (String(x.speaker_name || '').trim() || 'Speaker') + ': ' + String(x.text || '').trim())
  .join('\n');
const LIMIT = 120000;
if (transcriptText.length > LIMIT) transcriptText = transcriptText.slice(0, LIMIT) + '\n[Transcript shortened]';

const when = Number(t.date) ? DateTime.fromMillis(Number(t.date), { zone: $now.zoneName }).toFormat('d LLL yyyy, HH:mm') : '';

return [{
  json: {
    meetingId: t.id,
    title: String(t.title || '').trim() || 'Untitled call',
    callDate: when,
    durationMinutes: Math.round(Number(t.duration) || 0),
    contactEmail,
    contactName,
    transcriptText,
    hasSpeech: sentences.length > 0,
    firefliesLink: 'https://app.fireflies.ai/view/' + t.id
  }
}];

